<script>(()=>{const c=document.getElementById('signatureCanvas');if(!c)return;const x=c.getContext('2d');x.lineWidth=2;x.lineCap='round';let drawing=false,used=false;const point=e=>{const r=c.getBoundingClientRect(),p=e.touches?.[0]??e;return [(p.clientX-r.left)*c.width/r.width,(p.clientY-r.top)*c.height/r.height]};const start=e=>{drawing=true;used=true;x.beginPath();x.moveTo(...point(e));e.preventDefault()},move=e=>{if(!drawing)return;x.lineTo(...point(e));x.stroke();e.preventDefault()},stop=()=>drawing=false;c.addEventListener('mousedown',start);c.addEventListener('mousemove',move);addEventListener('mouseup',stop);c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',stop);document.getElementById('clearSignature').onclick=()=>{x.clearRect(0,0,c.width,c.height);used=false};document.getElementById('customerSignForm').addEventListener('submit',()=>{if(used)document.getElementById('signatureData').value=c.toDataURL('image/png')})})()</script>
